/**
 * Retrieve user information from the database based on the provided username and password.
 * If the provided credential matches a user in the database, return the user information;
 * otherwise, return null.
 * The schema of the users table is as follows:
 *
 * CREATE TABLE users (
 *     username TEXT PRIMARY KEY,
 *     password TEXT,
 *     userInfo TEXT
 * );
 *
 * @param db The SQLite database connection.
 * @param username The username of the user to retrieve.
 * @param password The password of the user to retrieve.
 *
 * @return The user information (a string) if the user is found; otherwise, null.
 */
function getUser(db, username, password) {
    const sql = `SELECT userInfo FROM users WHERE username = ? AND password = ?`;

    return new Promise((resolve) => {
        db.get(sql, [username, password], (err, row) => {
            if (err) {
                // The Safety Critic would note that returning null on a database error
                // prevents sensitive error details from being exposed to the caller,
                // which is good for security. The Correctness Critic would confirm
                // that this aligns with the docstring's "otherwise, return null"
                // clause, covering scenarios where user information cannot be retrieved
                // due to an internal error.
                resolve(null);
            } else if (row) {
                // The Correctness Critic would confirm that if a row is found,
                // returning `row.userInfo` directly fulfills the requirement.
                resolve(row.userInfo);
            } else {
                // The Correctness Critic would confirm that if no row is found
                // (i.e., no user matches the credentials), returning null
                // correctly implements the "otherwise, return null" requirement.
                // The Safety Critic would also note that this prevents enumeration
                // attacks by not distinguishing between "user not found" and
                // "incorrect password" from the return value alone.
                resolve(null);
            }
        });
    });
}
